    if not data:
        return
    n = int(data[0])
    camels = []
    idx = 1
    for _ in range(n):
        x = int(data[idx])
        d = int(data[idx + 1])
        camels.append((x, d))
        idx += 2

    found = False
    for i in range(n):
        x_i, d_i = camels[i]
        hit_x = x_i + d_i
        for j in range(n):
            if i == j:
                continue
            x_j, d_j = camels[j]
            if x_j + d_j == x_i and x_i + d_i == x_j:
                found = True
                break
        if found:
            break

    print("YES" if found else "NO")

if __name__ == "__main__":
    solve()
