def solve():
    n = int(input())
    a = list(map(int, input().split()))
    sum_total = sum(a)

    # Precompute prefix sums for odd and even positions
    prefix_odd = [0] * (n + 1)
    prefix_even = [0] * (n + 1)

    for i in range(1, n + 1):
        if i % 2 == 1:
            prefix_odd[i] = prefix_odd[i - 1] + a[i - 1]
            prefix_even[i] = prefix_even[i - 1]
        else:
            prefix_odd[i] = prefix_odd[i - 1]
            prefix_even[i] = prefix_even[i - 1] + a[i - 1]

    result = 0
    for i in range(1, n + 1):
        ai = a[i - 1]
        left_odd = prefix_odd[i - 1]

        if i % 2 == 1:
            # i is odd, want even positions after i
            right_sum = prefix_even[n] - prefix_even[i]
        else:
            # i is even, want odd positions after i
            right_sum = prefix_odd[n] - prefix_odd[i]

        sum_odd = left_odd + right_sum

        # Check if sum_odd == (sum_total - ai) / 2
        if (sum_total - ai) % 2 == 0 and sum_odd == (sum_total - ai) // 2:
            result += 1

    print(result)

if __name__ == "__main__":
    solve()
