import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    intervals = []
    index = 1

    for i in range(n):
        l = int(data[index])
        r = int(data[index + 1])
        intervals.append((l, r))
        index += 2

    # Find the union of all intervals
    sorted_intervals = sorted(intervals)
    union = []

    # Merge intervals
    for l, r in sorted_intervals:
        if not union or union[-1][1] < l - 1:
            union.append([l, r])
        else:
            union[-1][1] = max(union[-1][1], r)

    # Check each TV
    for i in range(n):
        l, r = intervals[i]
        # Check if this TV's interval is fully covered by the union of other intervals
        # We need to check if [l, r] is covered by union of all intervals except this one

        # Find union of all intervals except intervals[i]
        other_union = []
        for j in range(n):
            if j == i:
                continue
            l2, r2 = intervals[j]
            if not other_union or other_union[-1][1] < l2 - 1:
                other_union.append([l2, r2])
            else:
                other_union[-1][1] = max(other_union[-1][1], r2)

        # Check coverage
        covered = True
        current = 0
        for interval in other_union:
            if current >= r:
                break
            if interval[0] > l:
                # Gap between previous coverage and this interval
                covered = False
                break
            current = max(current, interval[1])

        if covered:
            print(i + 1)
            return

    print(-1)

if __name__ == "__main__":
    solve()
"}

