import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    coords = []
    for _ in range(n + m):
        coords.append(int(next(it)))

    types = []
    for _ in range(n + m):
        types.append(int(next(it)))

    # Separate coordinates and types for riders and taxi drivers
    taxi_coords = []
    rider_coords = []

    for i in range(n + m):
        if types[i] == 1:
            taxi_coords.append(coords[i])
        else:
            rider_coords.append(coords[i])

    # Use binary search to find closest taxi for each rider
    res = [0] * m

    for rider_pos in rider_coords:
        closest_idx = -1
        closest_dist = float('inf')

        for i, taxi_pos in enumerate(taxi_coords):
            dist = abs(rider_pos - taxi_pos)
            if dist < closest_dist or (dist == closest_dist and taxi_pos < taxi_coords[closest_idx]):
                closest_idx = i
                closest_dist = dist

        res[closest_idx] += 1

    print(' '.join(map(str, res)))

if __name__ == "__main__":
    solve()
"}

