def bfs(level, graph, match_to, n_right):
    """BFS to find augmenting paths"""
    queue = deque()
    for u in range(1, n_right + 1):
        if match_to[u] == -1:
            level[u] = 0
            queue.append(u)
        else:
            level[u] = -1

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if level[v] == -1:
                level[v] = level[u] + 1
                queue.append(v)
    return level

def dfs(u, level, graph, match_to):
    """DFS to find augmenting path"""
    for v in graph[u]:
        if level[v] == level[u] + 1:
            if dfs(match_to[v], level, graph, match_to):
                match_to[v] = u
                return True
    level[u] = -1
    return False

