def matches(word, pattern):
    """Check if word matches the pattern where '?' can be any character or empty."""
    i = 0  # index for word
    j = 0  # index for pattern

    # Match all characters until we run out of either
    while i < len(word) and j < len(pattern):
        if pattern[j] == '?':
            # '?' can match any character or be empty (skip)
            # Match it with current word character
            if word[i] == pattern[j]:
                i += 1
                j += 1
            else:
                # '?' can be empty, skip word character
                i += 1
                j += 1
        else:
            # Normal character match
            if word[i] == pattern[j]:
                i += 1
                j += 1
            else:
                return False

    # After matching, check if we've accounted for all '?' characters
    # If we still have '?' characters left, they must be skipped
    return j >= len(pattern) and i <= len(word)

n, m = map(int, input().split())

# Read all words
words = [input().strip() for _ in range(n)]

# Process each pattern
for _ in range(m):
    pattern = input().strip()

    # Count matches
    total = 0
    for word in words:
        if matches(word, pattern):
            total += 1

    print(total)
