import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    patterns = data[1:1+n]

    m = len(patterns[0])

    result = []
    for i in range(m):
        chars = set()
        for p in patterns:
            c = p[i]
            if c != '?':
                chars.add(c)
        if len(chars) == 1:
            result.append(chars.pop())
        else:
            result.append('?')

    print(''.join(result))

if __name__ == '__main__':
    solve()
