# Xenia and Weights problem

s = input().strip()
m = int(input())

# Parse available weights
available = [False] * 11
for i in range(10):
    if s[i] == '1':
        available[i + 1] = True

# Recursive backtracking with pruning
# We'll store the current path and sums

def backtrack(pos, last_weight, left_sum, right_sum, path):
    if pos == m:
        # We've placed all m weights
        return True, path

    # Determine which pan to place the next weight
    next_turn_left = (pos % 2 == 0)  # True means left pan, False means right pan

    # Try all available weights
    for weight in range(1, 11):
        if weight == last_weight:
            continue  # Skip if same as previous weight
        if not available[weight]:
            continue  # Skip if weight not available

        if next_turn_left:
            # Place on left pan
            if left_sum + weight > right_sum:
                path.append(weight)
                result, result_path = backtrack(pos + 1, weight, left_sum + weight, right_sum, path)
                if result:
                    return True, result_path
                path.pop()
        else:
            # Place on right pan
            if right_sum + weight > left_sum:
                path.append(weight)
                result, result_path = backtrack(pos + 1, weight, left_sum, right_sum + weight, path)
                if result:
                    return True, result_path
                path.pop()

    # No valid weight found at this position
    return False, None

# Start backtracking from position 0 with no previous weight
path = []
found, result_path = backtrack(0, -1, 0, 0, path)

if found:
    print("YES")
    print(' '.join(map(str, result_path)))
else:
    print("NO")
