    n, m = map(int, input().split())

    # Build adjacency list and in-degree array
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for _ in range(m):
        a, b = map(int, input().split())
        adj[a].append(b)
        in_degree[b] += 1

    # Find topological order using Kahn's algorithm
    queue = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    order = []
    while queue:
        u = queue.pop(0)
        order.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check if we got a valid topological order
    if len(order) != n:
        print(-1)
        return

    # Check if this order satisfies the constraint
    # No node should have an edge to its immediate successor
    for i in range(n - 1):
        u = order[i]
        v = order[i + 1]
        if v in adj[u]:
            # Try to find a different topological order by modifying the graph
            # Let's try to start from v instead of u
            # Clear in-degree and try again starting from v
            new_in_degree = in_degree[:]
            new_adj = [[] for _ in range(n + 1)]
