    # Find all indices where value is positive
    positive_indices = [i for i, val in enumerate(a) if val >= 0]

    # Create map from value to list of positive indices
    value_to_indices = {}
    for i in positive_indices:
        val = a[i]
        if val not in value_to_indices:
            value_to_indices[val] = []
        value_to_indices[val].append(i)

    max_sum = -float('inf')
    best_i = best_j = -1

    # For each positive index i, try to find best j > i with same value
    for i in positive_indices:
        val = a[i]
        indices_list = value_to_indices[val]

        # Find the last index j > i in this list
        for j_idx, j in enumerate(indices_list):
            if j > i:
                best_j_for_i = j

                # Now calculate sum of positive values in range [i, j]
                current_sum = 0
                for k in range(i, j + 1):
                    if a[k] >= 0:
                        current_sum += a[k]

                if current_sum > max_sum:
                    max_sum = current_sum
                    best_i = i
