import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    seen = {}
    insert_count = 0
    prefix_sum = 0

    for i, ai in enumerate(a):
        prefix_sum += ai

        if prefix_sum in seen:
            # We need to insert something
            insert_count += 1
            seen[prefix_sum] = False  # Mark this prefix sum as having been 'used'

            # Adjust prefix sum by adding the original value to 'break' the duplicate
            prefix_sum += ai
        else:
            seen[prefix_sum] = True

    print(insert_count)

if __name__ == "__main__":
    solve()
