{"code": "
t = int(input())
for _ in range(t):
    n, k = map(int, input().split())
    h = list(map(int, input().split()))

    # Function to find where a boulder stops
    def throw_boulder():
        i = 0  # start at the first mountain (0-indexed)
        while i < n - 1:
            # If current mountain is >= next mountain, roll
            if h[i] >= h[i + 1]:
                i += 1
            else:
                # Otherwise, stop at current mountain
                h[i] += 1
                return i + 1  # return 1-indexed position
        # Reached the last mountain, falls into system
        return -1

    # Simulate each boulder
    position = -1
    for boulder in range(1, k + 1):
        pos = throw_boulder()
        if pos == -1:
            # Boulder fell into system
            position = -1
        else:
            # Boulder stopped at position pos
            position = pos

    print(position)
