import sys
import math

def lipschitz_constant(arr):
    """Compute the Lipschitz constant for an array."""
    n = len(arr)
    if n < 2:
        return 0

    max_diff = 0
    min_distance = n  # max possible distance

    for i in range(n):
        for j in range(i + 1, n):
            diff = abs(arr[i] - arr[j])
            dist = j - i

            if diff > max_diff or (diff == max_diff and dist < min_distance):
                max_diff = diff
                min_distance = dist

    return math.ceil(max_diff / min_distance)

def solve():
    """Solve the problem."""
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    h = []
    for _ in range(n):
        h.append(int(next(it)))

    for _ in range(q):
        l = int(next(it)) - 1  # Convert to 0-indexed
        r = int(next(it)) - 1

        # Calculate sum of Lipschitz constants for all subarrays within [l, r]
        total = 0
        for start in range(l, r + 1):
            for end in range(start + 1, r + 1):
                sub = h[start:end + 1]
                total += lipschitz_constant(sub)

        print(total)

if __name__ == "__main__":
    solve()
