    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    patterns = data[1:1+n]

    # For each position, collect characters (excluding '?')
    # We'll use a list of sets
    pos_chars = []
    for i in range(len(patterns[0])):
        chars = set()
        for pattern in patterns:
            c = pattern[i]
            if c != '?':
                chars.add(c)
        pos_chars.append(chars)

    # Build result
    result = []
    for chars in pos_chars:
        if len(chars) == 0:
            result.append('a')  # all are '?', use 'a'
        elif len(chars) == 1:
            result.append(chars.pop())
        else:
            result.append('?')

    print(''.join(result))

if __name__ == '__main__':
    solve()
