import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    k = int(data[0])
    q = data[1] if len(data) > 1 else ""

    # If k > len(q), it's impossible
    if k > len(q):
        print("NO")
        return

    # We need k distinct characters as first characters of each part
    # Try all combinations of k distinct characters from the string
    from itertools import combinations, product

    # Get all positions of each character
    char_positions = {}
    for i, char in enumerate(q):
        if char not in char_positions:
            char_positions[char] = []
        char_positions[char].append(i)

    # Try all combinations of k distinct characters
    for first_chars in combinations(char_positions.keys(), k):
        # Try all permutations of these characters
        for perm in product([first_chars], repeat=k):
            # perm[0] is the tuple of first characters
            first_chars_list = list(perm[0])

            # Try to construct the sequence
            current_pos = 0
            parts = []
            valid = True

            for first_char in first_chars_list:
                # Find the next occurrence of first_char after current_pos
                found_pos = None
                for pos in char_positions[first_char]:
                    if pos >= current_pos:
                        found_pos = pos
                        break

                if found_pos is None:
                    valid = False
                    break

                # Take part from current_pos to found_pos
                parts.append(q[current_pos:found_pos])
                current_pos = found_pos

            if valid and current_pos == len(q):
                print("YES")
                for part in parts:
                    print(part)
                return

    print("NO")

if __name__ == "__main__":
    solve()
