def has_perfect_matching(graph, n):
    """Check if there's a perfect matching in a bipartite graph using DFS"""
    match_to = [-1] * n  # Match for each factory

    def dfs(factory):
        for airport in graph[factory]:
            if airport not in visited:
                visited.add(airport)
                if match_to[airport] == -1 or dfs(match_to[airport]):
                    match_to[airport] = factory
                    return True
        return False

    for factory in range(n):
        visited = set()
        if not dfs(factory):
            return False
    return True

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    idx += 1
    m = int(data[idx])
    idx += 1

    # Build adjacency list with weights
    graph = [[] for _ in range(n)]
    for _ in range(m):
        u = int(data[idx]) - 1  # airports are 0-indexed
        idx += 1
        v = int(data[idx]) - 1  # factories are 0-indexed
        idx += 1
        d = int(data[idx])
        idx += 1
        graph[v].append((u, d))  # Store airport and weight

    # Binary search on answer
    low = 1
    high = 10**9
    answer = -1

    while low <= high:
