        # Build graph with only edges ≤ mid
        temp_graph = [[] for _ in range(n)]
        for factory in range(n):
            for airport, weight in graph[factory]:
                if weight <= mid:
                    temp_graph[factory].append(airport)

        # Check for perfect matching
        if has_perfect_matching(temp_graph, n):
            answer = mid
            high = mid - 1
        else:
            low = mid + 1

