def compute_grundy(n):
    if n <= 0:
        return 0
    # Check all possible k >= 2
    # For given k, a = (n + k*(k-1)/2) / k must be integer
    # Also a >= k (since a >= k+1/2 > k for k >= 2)
    grundy = 0
    for k in range(2, n + 1):
        numerator = n + k * (k - 1) // 2
        if numerator % k == 0:
            a = numerator // k
            if a >= k:
                # Split into sizes: a, a-1, ..., a-k+1
                # Compute XOR of Grundy numbers of these sizes
                xor_sum = 0
                for i in range(k):
                    xor_sum ^= compute_grundy(a - i)
                # We need to find if there's a move that leaves grundy = 0
                if xor_sum == 0:
                    return k
    return -1

def solve():
    n = int(input())
    result = compute_grundy(n)
    print(result)

