def compute_grundy(n, memo):
    if n <= 0:
        return 0
    if n in memo:
        return memo[n]
    # Check all possible k >= 2
    grundy = 0
    for k in range(2, n + 1):
        numerator = n + k * (k - 1) // 2
        if numerator % k == 0:
            a = numerator // k
            if a >= k:
                # Split into sizes: a, a-1, ..., a-k+1
                xor_sum = 0
                for i in range(k):
                    xor_sum ^= compute_grundy(a - i, memo)
                if xor_sum == 0:
