def solve():
    import sys
    from collections import deque

    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(n - 1):
        u = int(data[idx])
        v = int(data[idx + 1])
        adj[u].append(v)
        adj[v].append(u)
        idx += 2

    # Count pairs at distance k using BFS
    # We'll count each pair exactly once
    total = 0

    # For each node, perform BFS and count how many nodes are at distance k
    for start in range(1, n + 1):
        # Use a queue for BFS
        q = deque([(start, 0)])  # (node, distance from start)
        visited = {start: True}

        while q:
            node, dist = q.popleft()

            # If we've reached distance k-1, look at neighbors
            if dist == k - 1:
                for neighbor in adj[node]:
                    if neighbor not in visited:
                        total += 1

            # If we've passed distance k-1, don't explore further
            if dist > k - 1:
                continue

            # For each neighbor, if not visited, add to queue and update distances
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited[neighbor] = True
                    new_dist = dist + 1
                    q.append((neighbor, new_dist))

    print(total)

if __name__ == "__main__":
    solve()
"}

