def solve(a, b):
    """Find the minimum number of resistors to achieve resistance a/b"""

    # Base case: resistance is 1
    if a == b:
        return 1

    # If resistance > 1, it must be from a series connection
    # a/b = (a/b - 1) + 1 => a/b - 1 = (a - b)/b
    if a > b:
        return 1 + solve(a - b, b)

    # If resistance < 1, it must be from a parallel connection
    # a/b = R / (R + 1) => R = a/(b - a)
    if a < b:
        return 1 + solve(a, b - a)

a, b = map(int, input().split())
print(solve(a, b))
