def solve():
    n, m = map(int, input().split())

    # Build adjacency list and in-degree count
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for _ in range(m):
        a, b = map(int, input().split())
        adj[a].append(b)
        in_degree[b] += 1

    # Topological sort using Kahn's algorithm
    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
    order = []

    while queue:
        u = queue.pop(0)
        order.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check if we have a valid order
    if len(order) != n:
        print(-1)
    else:
        # Check if any consecutive pair violates the condition
        valid = True
        for i in range(n - 1):
            u = order[i]
            v = order[i + 1]
            if v in adj[u]:
                valid = False
                break

        if valid:
            print(' '.join(map(str, order)))
        else:
            print(-1)

