    # Function to check if a number is prime
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    # Function to find the smallest prime factor of a number
    def smallest_prime_factor(x):
        if is_prime(x):
            return x
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return i

    # Function to find the greatest divisor (other than itself)
    def greatest_divisor(x):
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return x // i
        return None  # should never happen if x > 1

    # Separate b into primes and composites
    primes_in_b = set(x for x in b if is_prime(x))
    composites_in_b = [x for x in b if not is_prime(x)]

    a = []

    # For each composite in b, try to find its corresponding number in a
    for c in composites_in_b:
        # c = greatest_divisor(n) = n / smallest_prime_factor(n)
        # So n = c * smallest_prime_factor(n)
        # We need to find an n in b such that n = c * spf(n) and c is in b

        # Try all possible numbers in b as candidates for n
        for n_candidate in primes_in_b:
            # Check if n_candidate = c * spf(n_candidate)
            spf_n_candidate = smallest_prime_factor(n_candidate)
            if spf_n_candidate != c:
                continue

            # Check if c is indeed the greatest divisor of n_candidate
            if greatest_divisor(n_candidate) == c:
                a.append(c)
                primes_in_b.remove(n_candidate)
