    for c in composites_in_b:
        # c = greatest_divisor(n) = n / smallest_prime_factor(n)
        # So n = c * smallest_prime_factor(n)
        # We need to find an n in b such that n = c * spf(n) and c is in b

        # Try all possible numbers in b as candidates for n
        for n_candidate in primes_in_b:
            # Check if n_candidate = c * spf(n_candidate)
            spf_n_candidate = smallest_prime_factor(n_candidate)
            if spf_n_candidate != c:
                continue

            # Check if c is indeed the greatest divisor of n_candidate
            if greatest_divisor(n_candidate) == c:
                a.append(c)
                primes_in_b.remove(n_candidate)
                break

    # The remaining primes in primes_in_b must be elements of a
    a.extend(primes_in_b)

    # Output a
    print(' '.join(map(str, a)))

