    n = int(input())
    v = n  # The value to multiply (could be any number)
    target = n * v  # We want to reach target = n*v

    # Use BFS to find the shortest sequence of operations
    from collections import deque

    # Initial state: all registers contain 0 except eax contains v
    registers = {f"{chr(ord('a') + i)}x": 0 for i in range(26)}
    registers["eax"] = v

    # State: (registers, operations)
    initial_state = (registers.copy(), [])

    queue = deque([initial_state])
    visited = set()

    def state_key(state):
        registers, ops = state
        return tuple((reg, val) for reg, val in sorted(registers.items()))

    visited.add(state_key(initial_state))

    while queue:
        state, ops = queue.popleft()
        registers, ops = state

        # Check if any register contains the target
        for reg, val in registers.items():
            if val == target:
                print(len(ops))
                for op in ops:
                    print(op)
                return

        # Try all possible operations
        # Operation 1: lea x, [y]
        for x, y in [(reg1, reg2) for reg1 in registers for reg2 in registers]:
            if x != y:
                new_regs = registers.copy()
                new_regs[x] = new_regs[y]
                new_state = (new_regs, ops + [f"lea {x}, [{y}]"])
                key = state_key(new_state)
                if key not in visited:
                    visited.add(key)
                    queue.append(new_state)

        # Operation 2: lea x, [y + z]
        for x, y, z in [(reg1, reg2, reg3) for reg1 in registers for reg2 in registers for reg3 in registers]:
