def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    L = int(data[idx]); idx += 1

    ramps = []
    for i in range(n):
        xi = int(data[idx]); idx += 1
        di = int(data[idx]); idx += 1
        ti = int(data[idx]); idx += 1
        pi = int(data[idx]); idx += 1
        ramps.append((xi, di, ti, pi, i + 1))

    best_time = L
    best_ramps = []

    # Try using no ramps
    best_time = L
    best_ramps = []

    # Try using one ramp
    for xi, di, ti, pi, num in ramps:
        if xi >= pi:
            time = L - di + ti
            if time < best_time:
                best_time = time
                best_ramps = [num]

    # Try using two ramps in order
    for i in range(n):
        xi1, di1, ti1, pi1, num1 = ramps[i]
        for j in range(n):
            if i == j:
                continue
            xi2, di2, ti2, pi2, num2 = ramps[j]

            if xi1 >= pi1:
                # After first ramp, we're at position xi1 + di1
                # Need to reach gathering point for second ramp: xi2 - pi2
                if xi1 + di1 >= xi2 - pi2 and xi2 >= pi2:
                    time = L - di1 - di2 + ti1 + ti2
                    if time < best_time:
                        best_time = time
                        best_ramps = [num1, num2]

    # Try using three ramps
    for i in range(n):
        xi1, di1, ti1, pi1, num1 = ramps[i]
        for j in range(n):
            if i == j:
                continue
            xi2, di2, ti2, pi2, num2 = ramps[j]
            for k in range(n):
                if i == k or j == k:
                    continue
                xi3, di3, ti3, pi3, num3 = ramps[k]

                if xi1 >= pi1 and xi2 >= pi2 and xi3 >= pi3:
                    if xi1 + di1 >= xi2 - pi2 and xi2 + di2 >= xi3 - pi3:
                        time = L - di1 - di2 - di3 + ti1 + ti2 + ti3
                        if time < best_time:
                            best_time = time
                            best_ramps = [num1, num2, num3]

    print(best_time)
    print(len(best_ramps))
    if best_ramps:
        print(' '.join(map(str, best_ramps)))

solve()
