n = int(input())
values = list(map(int, input().split()))

# Find all indices where each value occurs
from collections import defaultdict
value_indices = defaultdict(list)
for idx, val in enumerate(values):
    value_indices[val].append(idx)

max_sum = float('-inf')
cut_indices = []

# Try each possible value as the starting/ending value
for val in set(values):
    # Get all indices with this value
    indices = value_indices[val]

    # Try each possible pair of starting and ending indices
    for start_idx in indices:
        for end_idx in indices:
            if start_idx >= end_idx:
                continue

            # Calculate sum of trees with positive values between start_idx and end_idx (inclusive)
            current_sum = 0
            cut = []
            for i in range(start_idx, end_idx + 1):
                if values[i] > 0:
                    current_sum += values[i]
                else:
                    cut.append(i + 1)  # 1-indexed

            # Check if we have at least two trees left
            # We need to ensure there's at least one tree between start and end, or exactly two trees
            if start_idx + 1 <= end_idx or start_idx == end_idx - 1:
                # At least two trees left
                if current_sum > max_sum:
                    max_sum = current_sum
                    cut_indices = cut

# Output the result
print(f"{max_sum} {len(cut_indices)}")
if cut_indices:
    print(' '.join(map(str, cut_indices)))
