def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Check if array is already non-decreasing
        if all(a[i] <= a[i+1] for i in range(n-1)):
            print("YES")
            continue

        # Count number of inversions (parities of swaps needed)
        inversions = 0
        for i in range(n):
            for j in range(i+1, n):
                if a[i] > a[j]:
                    inversions += 1

        # If even number of inversions, possible; otherwise not
        print("YES" if inversions % 2 == 0 else "NO")

solve()
