import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    distinct_or = set()

    for i in range(n):
        current_or = 0
        for j in range(i, n):
            current_or |= a[j]
            distinct_or.add(current_or)

            # If current_or stops changing, break early
            if current_or == a[j]:
                break

    print(len(distinct_or))

if __name__ == "__main__":
    main()
"}

