def topological_sort(n, adj):
    in_degree = [0] * (n + 1)

    # Calculate in-degrees
    for u in range(1, n + 1):
        for v in adj[u]:
            in_degree[v] += 1

    # Kahn's algorithm
    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
    result = []

    while queue:
        u = queue.pop(0)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != n:
        return -1
    return result

def solve():
    data = input().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        a = int(input().split()[0])
        b = int(input().split()[1])
        adj[a].append(b)

    order = topological_sort(n, adj)

    if order == -1:
        print(-1)
    else:
        print(' '.join(map(str, order)))

solve()
