def solve():
    # Read input
    weights_available = input().strip()
    m = int(input())

    # Find available weights
    available_weights = [i+1 for i, has_weight in enumerate(weights_available) if has_weight == '1']

    # DP: position, left_sum, right_sum, last_weight, current_pan -> tuple (can_reach, path)
    # current_pan: 0 for left, 1 for right
    memo = {}

    def can_place(pos, left, right, last, pan):
        # Base case: all weights placed
        if pos == m:
            return (True, [])

        # Memoization
        key = (pos, left, right, last, pan)
        if key in memo:
            return memo[key]

        # Try all available weights
        for weight in available_weights:
            # Check if weight is different from last weight
            if last is not None and weight == last:
                continue

            # Calculate new sums
            if pan == 0:  # Left pan
                new_left = left + weight
                new_right = right
            else:  # Right pan
                new_left = left
                new_right = right + weight

            # Check if the scalepan with the new weight outweighs the other
            if pan == 0 and new_left <= new_right:
                continue
            if pan == 1 and new_right <= new_left:
                continue

            # Recursively check
            can_reach, path = can_place(pos + 1, new_left, new_right, weight, 1 - pan)
            if can_reach:
                memo[key] = (True, [weight] + path)
                return (True, [weight] + path)

        memo[key] = (False, [])
        return (False, [])

    # Try all possible starting weights
    for start_weight in available_weights:
        result, path = can_place(1, start_weight, 0, start_weight, 1)
        if result:
            print("YES")
            print(' '.join(map(str, path)))
            return

    print("NO")

solve()
