import sys

def solve() -> None:
    n = int(sys.stdin.readline())
    patterns = [sys.stdin.readline().strip() for _ in range(n)]

    # For each position, find the set of characters across all patterns
    # If there's a character that appears in all patterns (not '?'), use that character
    # If '?' appears in all patterns, we can put any character (we'll use 'a')
    # If there's a mix, we need to check if we can put a specific character that works for all
    # Actually, if we put a specific character, it must be compatible with all patterns at that position
    # A character is compatible with a pattern if either the pattern has that character or it has '?'.

