n, m, c0, d0 = map(int, input().split())

# Read stuffing information
stuffings = []
for _ in range(m):
    a, b, c, d = map(int, input().split())
    stuffings.append((a, b, c, d))

def solve():
    # dp[i] = maximum tugriks with i grams of dough
    dp = [-1] * (n + 1)
    dp[0] = 0  # No dough, no tugriks

    # Try all combinations of buns
    for dough in range(n + 1):
        if dp[dough] == -1:
            continue

        # Try making buns without stuffing
        if dough + c0 <= n:
            dp[dough + c0] = max(dp[dough + c0], dp[dough] + d0)

        # Try making buns with each stuffing type
        for a, b, c, d in stuffings:
            # Calculate max buns we can make with this stuffing
            max_buns = min(a // b, (n - dough) // c)

            # Try making 0, 1, ..., max_buns buns
            for k in range(1, max_buns + 1):
                if dough + k * c > n:
                    break
                dp[dough + k * c] = max(dp[dough + k * c], dp[dough] + k * d)

    # Find maximum tugriks
    return max(dp)

total = solve()
print(total)
