            # Try making 0, 1, ..., max_buns buns
            for k in range(1, max_buns + 1):
                new_dough = dough + k * c
                if new_dough > n:
                    break
                dp[new_dough] = max(dp[new_dough], dp[dough] + k * d)

    # Find maximum tugriks
    return max(dp)

