import sys
from collections import deque

def bfs_match(graph, n, m, match_to, visited):
    """Check if perfect matching exists using BFS"""
    for u in range(1, n + 1):
        if match_to[u] == -1:
            visited = [False] * (n + 1)
            if bfs(graph, u, match_to, visited):
                return True
    return False

def bfs(graph, u, match_to, visited):
    """BFS to find augmenting path"""
    q = deque()
    q.append(u)
    visited[u] = True

    while q:
        current = q.popleft()
        for v in graph[current]:
            if not visited[v]:
                visited[v] = True
                if match_to[v] == -1:
                    return True
                q.append(match_to[v])
    return False

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1

    # Build adjacency list with weights
    graph = [[] for _ in range(N + 1)]
    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        d = int(data[idx]); idx += 1
        graph[u].append((v, d))

    # Binary search on answer
    low = 1
    high = 10**18
    answer = -1

    while low <= high:
        mid = (low + high) // 2

        # Build graph with edges <= mid
        temp_graph = [[] for _ in range(N + 1)]
        for u in range(1, N + 1):
            for v, d in graph[u]:
                if d <= mid:
                    temp_graph[u].append(v)

        # Check if perfect matching exists
        match_to = [-1] * (N + 1)
        if bfs_match(temp_graph, N, N, match_to, [False] * (N + 1)):
            answer = mid
            high = mid - 1
        else:
            low = mid + 1

    print(answer)

solve()
