def solve():
    n = input().strip()
    digits = list(n)

    # Calculate sum of digits
    total = sum(int(d) for d in digits)

    # If sum is already divisible by 3
    if total % 3 == 0:
        # Check if it has leading zeros
        if n[0] == '0':
            # If all digits are 0, we can just output 0
            print(0)
        else:
            print(n)
        return

    r = total % 3

    best = None

    # Option 1: Try to remove one digit with remainder r (prefer from the end)
    indexed_digits = [(i, d) for i, d in enumerate(digits)]
    positions_r = [i for i, d in indexed_digits if int(d) % 3 == r]

    if positions_r:
        # Try to remove the rightmost digit with remainder r
        new_digits = digits[:]
        remove_idx = max(positions_r)
        new_digits.pop(remove_idx)

        # Check if this is a valid beautiful number
        if new_digits:
            if new_digits[0] == '0':
                first_non_zero = -1
                for i, d in enumerate(new_digits):
                    if d != '0':
                        first_non_zero = i
                        break
                if first_non_zero != -1:
                    candidate = ''.join(new_digits[first_non_zero:])
                else:
                    candidate = '0'
            else:
                candidate = ''.join(new_digits)

            if best is None or len(candidate) > len(best):
                best = candidate

    # Option 2: Try to remove two digits with remainder (3 - r) (prefer from the end)
    target = 3 - r
    positions_target = [i for i, d in indexed_digits if int(d) % 3 == target]

    if len(positions_target) >= 2:
        # Try to remove the two rightmost digits with this remainder
        new_digits = digits[:]
        positions_target.sort(reverse=True)
        remove_idx1 = positions_target[0]
        remove_idx2 = positions_target[1]

        # Remove them
        new_digits.pop(remove_idx1)
        new_digits.pop(remove_idx2)

        # Check if this is a valid beautiful number
