    n, k = map(int, input().split())
    tree = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        a, b = map(int, input().split())
        tree[a].append(b)
        tree[b].append(a)

    # dp[u][d] = number of nodes at distance d from node u
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    def dfs(u, parent):
        dp[u][0] = 1  # distance 0 from itself
        for v in tree[u]:
            if v != parent:
                dfs(v, u)
                for d in range(k):
                    dp[u][d + 1] += dp[v][d]

    dfs(1, -1)

    # Count pairs at distance k
    count = 0
    for u in range(1, n + 1):
        count += dp[u][k]

    # Each pair is counted twice, so divide by 2
    print(count // 2)

