def can_split(x, k):
    """Check if we can split x stones into k piles with differences of 1"""
    return (x + k * (k - 1) // 2) % k == 0

def grundy(x, memo):
    """Calculate Grundy number for a pile of size x"""
    if x in memo:
        return memo[x]

    # Base case: no move possible
    if x < 2:
        return 0

    moves = []
    # Try all possible k >= 2
    for k in range(2, x + 1):
        if can_split(x, k):
            moves.append(grundy(k, memo))

    # Calculate Grundy number
    result = 0
    for move in moves:
        result = max(result, move + 1)

    memo[x] = result
    return result

def solve():
    n = int(input())

    # Calculate Grundy number for n
    g = grundy(n, {})

    # If Grundy number is 0, Serozha loses
