def can_form_palindrome(frequencies):
    odd_count = 0
    for count in frequencies.values():
        if count % 2 != 0:
            odd_count += 1
    return odd_count <= 1

# Read input
s = input().strip()

# Count frequencies
from collections import Counter
frequencies = Counter(s)

# Check if can form palindrome immediately
if can_form_palindrome(frequencies):
    print("First")
else:
    # Count how many characters have odd frequencies
    odd_count = sum(1 for count in frequencies.values() if count % 2 != 0)

    # Game logic
    if odd_count == 0 or odd_count == 1:
        print("First")
    elif odd_count % 2 == 0:
        print("First")
    else:
        print("Second")
