    # Check if there are no overlapping bits between x and y
    if (x & y) != 0:
        print(0)
    else:
        # Count the number of set bits in x
        k = bin(x).count('1')

        # If y is 0, we cannot have all bits going to one number
        if y == 0:
            # Subtract 2 invalid cases (all bits to a or all to b)
            ans = 2**k - 2
            # But we need to ensure ans >= 0
            if ans < 0:
                ans = 0
        else:
            # y > 0, so all bits to one number is valid
            ans = 2**k

        print(ans)
