import sys

def count_differing_bits(x, y):
    """Count the number of bits that differ between x and y"""
    return bin(x ^ y).count('1')

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Count frequencies of each number
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Count pairs for k=0
    if k == 0:
        ans = 0
        for count in freq.values():
            ans += count * (count - 1) // 2
        print(ans)
        return

    # Count pairs for k > 0
    ans = 0
    nums = list(freq.keys())
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            diff = count_differing_bits(nums[i], nums[j])
            if diff == k:
                ans += freq[nums[i]] * freq[nums[j]]

    print(ans)

if __name__ == "__main__":
    solve()
"}

