n = int(input())
a = list(map(int, input().split()))

# Compute total sum
total_sum = sum(a)

# If total sum is not divisible by 3, answer is 0
if total_sum % 3 != 0:
    print(0)
else:
    target = total_sum // 3

    # Compute prefix sums
    prefix_sums = []
    current_sum = 0
    for i in range(n):
        current_sum += a[i]
        prefix_sums.append(current_sum)

    # Find valid i's (prefix sum == target)
    valid_i = []
    for i in range(n):
        if prefix_sums[i] == target:
            valid_i.append(i + 1)  # indices are 1-based

    # Find valid j's (prefix sum == 2 * target)
    valid_j = []
    for j in range(n):
        if prefix_sums[j] == 2 * target:
            valid_j.append(j + 1)  # indices are 1-based

    # Count valid splits
    count = 0
    for i in valid_i:
        # Find how many j's satisfy i < j <= n-1
        # j must be in valid_j and > i and <= n-1
        for j in valid_j:
            if i < j <= n - 1:
                count += 1

    print(count)
